// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { MultiSelect } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Inputs/MultiSelect)

figma.connect(MultiSelect, FIGMA_NODE_URL, {
  props: {
    placeholder: figma.string('placeholder'),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
    isDisabled: figma.boolean('isDisabled'),
    isInvalid: figma.boolean('isInvalid'),
    label: figma.string('label'),
    description: figma.string('description'),
    errorMessage: figma.string('errorMessage'),
  },
  example: ({ label, placeholder, size, isDisabled, isInvalid, description, errorMessage }) => (
    <MultiSelect placeholder={placeholder} size={size} isDisabled={isDisabled} isInvalid={isInvalid} description={description} errorMessage={errorMessage}>{label}</MultiSelect>
  ),
});
